-- stochastic-processes implementation for SobolSequence
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.

local Module = {}
function Module.VanDerCorput(index,base)
    assert(index>=0 and index%1==0 and base>=2 and base%1==0,"invalid low-discrepancy sequence arguments")
    local value=0; local fraction=1/base; local n=index
    while n>0 do value+=(n%base)*fraction; n=math.floor(n/base); fraction/=base end
    return value
end
function Module.OneDimensional(count)
    local out=table.create(count); for i=1,count do out[i]=Module.VanDerCorput(i-1,2) end; return out
end

return Module
